import{_ as n,a0 as p,w as d,s,ao as l,I as o,x as e,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"Attic——刪除重複數據的備份程序 | LCTT x X-CMD","titleTemplate":false,"description":"Attic——刪除重複數據的備份程序 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Attic——刪除重複數據的備份程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Attic——刪除重複數據的備份程序 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141219 Attic--Deduplicating backup program","title":"Attic——刪除重複數據的備份程序","tag":"201412","desc":""},"relativePath":"201412/20141219 Attic--Deduplicating backup program.md","filePath":"[post].md"}'),u={name:"201412/20141219 Attic--Deduplicating backup program.md"};function c(m,t,h,b,f,x){const a=p("Link");return d(),s("div",null,[t[16]||(t[16]=l(`<h1 id="attic——刪除重複數據的備份程序" tabindex="-1">Attic——刪除重複數據的備份程序 <a class="header-anchor" href="#attic——刪除重複數據的備份程序" aria-label="Permalink to “Attic——刪除重複數據的備份程序”">​</a></h1><p>Attic是一個Python寫的刪除重複數據的備份程序，其主要目標是提供一種高效安全的數據備份方式。重複數據消除技術的使用使得Attic適用於日常備份，因為它可以只存儲那些修改過的數據。</p><h3 id="attic特性" tabindex="-1">Attic特性 <a class="header-anchor" href="#attic特性" aria-label="Permalink to “Attic特性”">​</a></h3><h4 id="空間高效存儲" tabindex="-1">空間高效存儲 <a class="header-anchor" href="#空間高效存儲" aria-label="Permalink to “空間高效存儲”">​</a></h4><p>可變塊大小重複數據消除技術用於減少檢測到的冗餘數據存儲字節數量。每個文件被分割成若干可變長度組塊，只有那些從沒見過的組合塊會被壓縮並添加到倉庫中。</p><h4 id="可選數據加密" tabindex="-1">可選數據加密 <a class="header-anchor" href="#可選數據加密" aria-label="Permalink to “可選數據加密”">​</a></h4><p>所有數據可以使用256位AES加密進行保護，並使用HMAC-SHA256驗證數據完整性和真實性。</p><h4 id="離場備份" tabindex="-1">離場備份 <a class="header-anchor" href="#離場備份" aria-label="Permalink to “離場備份”">​</a></h4><p>Attic可以通過SSH將數據存儲到安裝有Attic的遠程主機上。</p><h4 id="備份可作為文件系統掛載" tabindex="-1">備份可作為文件系統掛載 <a class="header-anchor" href="#備份可作為文件系統掛載" aria-label="Permalink to “備份可作為文件系統掛載”">​</a></h4><p>備份歸檔可作為用户空間文件系統掛載，用於便捷地驗證和恢復備份。</p><h4 id="安裝attic到ubuntu-14-10" tabindex="-1">安裝attic到ubuntu 14.10 <a class="header-anchor" href="#安裝attic到ubuntu-14-10" aria-label="Permalink to “安裝attic到ubuntu 14.10”">​</a></h4><p>打開終端並運行以下命令</p><pre><code>sudo apt-get install attic
</code></pre><h3 id="使用attic" tabindex="-1">使用Attic <a class="header-anchor" href="#使用attic" aria-label="Permalink to “使用Attic”">​</a></h3><h4 id="手把手實例教學" tabindex="-1">手把手實例教學 <a class="header-anchor" href="#手把手實例教學" aria-label="Permalink to “手把手實例教學”">​</a></h4><p>在進行備份之前，首先要對倉庫進行初始化：</p><pre><code>$ attic init /somewhere/my-repository.attic
</code></pre><p>將~/src和~/Documents目錄備份到名為Monday的歸檔：</p><pre><code>$ attic create /somwhere/my-repository.attic::Monday ~/src ~/Documents
</code></pre><p>第二天創建一個新的名為Tuesday的歸檔：</p><pre><code>$ attic create --stats /somwhere/my-repository.attic::Tuesday ~/src ~/Documents
</code></pre><p>該備份將更快些，也更小些，因為只有之前從沒見過的新數據會被存儲。--stats選項會讓Attic輸出關於新創建的歸檔的統計數據，比如唯一數據（不和其它歸檔共享）的數量：</p><pre><code>歸檔名：Tuesday
歸檔指紋：387a5e3f9b0e792e91ce87134b0f4bfe17677d9248cb5337f3fbf3a8e157942a
開始時間： Tue Mar 25 12:00:10 2014
結束時間： Tue Mar 25 12:00:10 2014
持續時間： 0.08 seconds
文件數量： 358
        最初大小    壓縮後大小  重複數據刪除後大小
本歸檔： 57.16 MB    46.78 MB    151.67 kB
所有歸檔：114.02 MB  93.46 MB    44.81 MB
</code></pre><p>列出倉庫中所有歸檔：</p><pre><code>$ attic list /somewhere/my-repository.attic

Monday Mon Mar 24 11:59:35 2014
Tuesday Tue Mar 25 12:00:10 2014
</code></pre><p>列出Monday歸檔的內容：</p><pre><code>$ attic list /somewhere/my-repository.attic::Monday

drwxr-xr-x user group 0 Jan 06 15:22 home/user/Documents
-rw-r--r-- user group 7961 Nov 17 2012 home/user/Documents/Important.doc
</code></pre><p>恢復Monday歸檔：</p><pre><code>$ attic extract /somwhere/my-repository.attic::Monday
</code></pre><p>通過手動刪除Monday歸檔恢復磁盤空間：</p><pre><code>$ attic delete /somwhere/my-backup.attic::Monday
</code></pre>`,32)),o("p",null,[t[1]||(t[1]=e("詳情請查閲",-1)),r(a,{href:"https://attic-backup.org/index.html"},{default:i(()=>[...t[0]||(t[0]=[e("Attic文檔",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[17]||(t[17]=o("hr",null,null,-1)),o("p",null,[t[4]||(t[4]=e("via: ",-1)),r(a,{href:"http://www.ubuntugeek.com/attic-deduplicating-backup-program.html"},{default:i(()=>[...t[3]||(t[3]=[e("http://www.ubuntugeek.com/attic-deduplicating-backup-program.html",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("作者：",-1)),r(a,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:i(()=>[...t[5]||(t[5]=[e("ruchi",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),r(a,{href:"https://github.com/GOLinux"},{default:i(()=>[...t[6]||(t[6]=[e("GOLinux",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:i(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),r(a,{href:"http://linux.cn/"},{default:i(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const g=n(u,[["render",c]]);export{A as __pageData,g as default};
